public class Main {
  public static void main(String[] args) {
    int[][] arr = {{1, 2, 3}, {4, 5, 6}};

    for (int[] x : arr) {
        for (int y : x) {
            System.out.println(y);
        }
    }
  }
}

// En Java no hay un equivalente nativo a nditer.
// Para un array 3-D:
for(int[][] x : arr) {
    for(int[] y : x) {
        for(int z : y) {
            System.out.println(z);
        }
    }
}
